{"policy_source":"'''Provisional policy design record.
Causal claim: an explicit probation/protected boundary separates initial admission from established reuse, making scan resistance and phase adaptation observable in the policy state.
Audit evidence: every eviction is removed from exactly one local cache segment, used_bytes is updated at each removal or insertion, and access returns only keys selected from those cached segments.
'''

from collections import OrderedDict


class Policy:
    def __init__(self, capacity_bytes: int):
        self.capacity_bytes = max(0, int(capacity_bytes))
        self.probation = OrderedDict()
        self.protected = OrderedDict()
        self.ghost = OrderedDict()
        self.used_bytes = 0
        self._frequency = {}
        self._clock = 0
        self._operations = 0
        self._protected_ratio = 50
        self._protected_hits = 0
        self._probation_hits = 0
        self._ghost_limit = 2048

    def _protected_target(self):
        if self.capacity_bytes == 0:
            return 0
        target = self.capacity_bytes * self._protected_ratio // 100
        return max(1, min(self.capacity_bytes, target))

    def _rebalance(self):
        target = self._protected_target()
        protected_bytes = sum(record[0] for record in self.protected.values())
        while self.protected and protected_bytes > target:
            key, record = self.protected.popitem(last=False)
            self.probation[key] = record
            protected_bytes -= record[0]

    def _remember(self, key):
        self.ghost.pop(key, None)
        self.ghost[key] = None
        while len(self.ghost) > self._ghost_limit:
            self.ghost.popitem(last=False)

    def _age_metadata(self):
        live = set(self.probation)
        live.update(self.protected)
        live.update(self.ghost)
        for key, value in list(self._frequency.items()):
            aged = value // 2
            if aged:
                self._frequency[key] = aged
            elif key in live:
                self._frequency[key] = 1
            else:
                del self._frequency[key]

    def _observe(self, key):
        self._clock += 1
        self._operations += 1
        self._frequency[key] = self._frequency.get(key, 0) + 1
        if self._operations % 256 == 0:
            if self._protected_hits > self._probation_hits * 2:
                self._protected_ratio = min(75, self._protected_ratio + 5)
            elif self._probation_hits > self._protected_hits * 2:
                self._protected_ratio = max(25, self._protected_ratio - 5)
            self._protected_hits = 0
            self._probation_hits = 0
            self._age_metadata()

    def _evict_probation(self):
        victim = min(
            self.probation,
            key=lambda candidate: (
                self._frequency.get(candidate, 1),
                self.probation[candidate][1],
                -self.probation[candidate][0],
            ),
        )
        size, _ = self.probation.pop(victim)
        self.used_bytes -= size
        self._remember(victim)
        return victim

    def _make_room(self, required_bytes):
        evicted = []
        self._rebalance()
        while self.used_bytes + required_bytes > self.capacity_bytes:
            if self.probation:
                evicted.append(self._evict_probation())
            elif self.protected:
                key, record = self.protected.popitem(last=False)
                self.probation[key] = record
            else:
                break
        return evicted

    def _resize_and_touch(self, key, size, protected):
        segment = self.protected if protected else self.probation
        old_size, _ = segment.pop(key)
        if size > self.capacity_bytes:
            self.used_bytes -= old_size
            self._remember(key)
            return [key]

        self.used_bytes += size - old_size
        segment[key] = (size, self._clock)
        if protected:
            self._protected_hits += 1
        else:
            self._probation_hits += 1
            record = self.probation.pop(key)
            self.protected[key] = record
        evicted = self._make_room(0)
        self._rebalance()
        return evicted

    def access(self, key: int, size: int, now: int) -> list[int]:
        del now
        size = max(0, int(size))
        self._observe(key)

        if key in self.protected:
            return self._resize_and_touch(key, size, True)
        if key in self.probation:
            return self._resize_and_touch(key, size, False)

        if self.capacity_bytes == 0 or size > self.capacity_bytes:
            return []

        ghost_hit = key in self.ghost
        if ghost_hit:
            self.ghost.pop(key, None)

        evicted = self._make_room(size)
        record = (size, self._clock)
        if ghost_hit:
            self.protected[key] = record
        else:
            self.probation[key] = record
        self.used_bytes += size
        self._rebalance()
        return evicted
